<h1 class="page-title">So sánh sản phẩm</h1><p class="muted">Chọn từ 2 đến 4 sản phẩm cùng danh mục để so sánh.</p><?php if(count($products)<2):?><div class="panel empty">Cần ít nhất 2 sản phẩm. <a href="/products">Chọn thêm sản phẩm</a></div><?php endif?><?php if($products):?><div class="panel table-wrap"><table class="table compare-table"><tbody><tr><th>Sản phẩm</th><?php foreach($products as $p):?><td><img src="<?= e($p['images'][0]['path']??'/assets/img/device-'.$p['category_id'].'.svg') ?>" alt="<?= e($p['name']) ?>"><h3><a href="/products/<?= $p['id'] ?>"><?= e($p['name']) ?></a></h3><form action="/compare/update" method="post" data-ajax data-reload="true"><?= App\Core\Csrf::field() ?><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><input type="hidden" name="action" value="remove"><button class="btn btn-light btn-sm" type="submit">Bỏ so sánh</button></form></td><?php endforeach?></tr><tr><th>Giá bán</th><?php foreach($products as $p):?><td><?= money($p['price']) ?></td><?php endforeach?></tr><tr><th>Thương hiệu</th><?php foreach($products as $p):?><td><?= e($p['brand_name']) ?></td><?php endforeach?></tr><?php foreach($keys as $key):?><tr><th><?= e($key) ?></th><?php foreach($products as $p):$spec=array_column($p['specs'],'spec_value','spec_key');?><td><?= e($spec[$key]??'—') ?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div><?php endif?>
